def equation(gate_voltage_abs: np.ndarray, parameters: np.ndarray) -> np.ndarray:
    """Equação empírica para log10(|ID|/A) ao longo da curva de transferência."""
    """Aiming for a third-degree polynomial capturing the strong curvature of the OTFT transfer characteristic curve."""
    return parameters[0] + parameters[1] * gate_voltage_abs + parameters[2] * (gate_voltage_abs - parameters[3])**2 + parameters[4] * (gate_voltage_abs - parameters[3])
